-- composition of rule kernels in_clause x outer_join_simplification (duckdb), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (SELECT a1.c0 AS c0, a1.c1 AS c1, a1.c2 AS c2, '{"k": -1, "a": [1, 2, 3]}'::jsonb AS c3 FROM t0 AS a1 GROUP BY a1.c1, a1.c2, a1.c0 HAVING (a1.c2 IN (MAX (a1.c2)))) AS ka UNION ALL SELECT 2 AS k FROM (SELECT a2.c0 AS c0, '2024-01-01 00:00:00+00'::timestamptz AS c1 FROM (tp AS a1 JOIN (t0 AS a2 LEFT JOIN (t1 POSITIONAL JOIN tp) ON ((a2.c1 = tp.c1) AND TRUE)) ON ((a1.c0 = tp.c0) AND ('abc'::text NOT ILIKE '%\\%'::text))) QUALIFY (COUNT (*) OVER () = 1)) AS kb) AS u;
